import{_ as e,c as p,o as r,ah as i}from"./chunks/framework.Dnh4IO1K.js";const _=JSON.parse('{"title":"59、【渙】 坎下巽上","description":"周易尚氏學 - 59、【渙】 坎下巽上","frontmatter":{"title":"59、【渙】 坎下巽上","description":"周易尚氏學 - 59、【渙】 坎下巽上"},"headers":[],"relativePath":"classics/shangshi/064.md","filePath":"classics/shangshi/064.md"}'),s={name:"classics/shangshi/064.md"};function t(h,a,l,n,c,d){return r(),p("div",null,[...a[0]||(a[0]=[i('<h1 id="_59、【渙】-坎下巽上" tabindex="-1">59、【渙】 坎下巽上 <a class="header-anchor" href="#_59、【渙】-坎下巽上" aria-label="Permalink to “59、【渙】 坎下巽上”">​</a></h1><p>舊解皆以風行水上。渙散為說。然如渙王居。渙其躬等爻辭。散義皆不通。按太玄擬渙為文。司馬光雲。揚子蓋讀渙為煥。案渙即有文義。淮南子說山訓。夫玉潤澤而有光。渙乎其有似也。註文採似君子也。後漢書延篤傳。渙爛其溢目。注渙爛文章貌。是渙本有文義。故歸藏作奐。禮檀弓。美哉奐焉。釋文奐本亦作煥。是揚子之讀。與古訓合。卦坎為赤。震為玄黃。巽為白。而風行水上。文理爛然。故為文也。為文則於爻辭無扦格矣。震為王。艮為廟。假至也。言王有事於宗廟。震為舟。在水上。故利涉。皆中爻象。</p><p>彖曰。渙亨 剛來而不窮。柔得位乎外而上同。王假有廟。王乃在中也。利涉大川。乘木有功也。</p><p>剛來居二。臨一陰則陷。二陰則通。故曰不窮。四當位。上承一陽固吉。承二陽尤吉。上同者與小畜六四。升初六之上合志同也。言孚於五上也。震為舟。古刳木為舟。五乘之。故曰乘木。乘木即乘舟。</p><p>象曰。風行水上。渙。先王以享於帝立廟。</p><p>亨帝則禮儀繁盛。立廟則楹桷巍煥。皆屬於文。正釋卦義也。</p><p>初六。用拯馬壯吉。</p><p>震為馬。初承之。故曰拯馬。鄭雲拯承也。拯馬即承陽。震健故壯吉。此與明夷六二象同。故辭同。故象傳皆以順釋之。拯順也。</p><h3 id="象曰。初六之吉。順也。" tabindex="-1">象曰。初六之吉。順也。 <a class="header-anchor" href="#象曰。初六之吉。順也。" aria-label="Permalink to “象曰。初六之吉。順也。”">​</a></h3><p>言陰順陽。以順釋拯義也。</p><p>九二。渙奔其機。悔亡。</p><p>焦循雲。漢百官公卿表。虎賁郎注。賁讀與奔同。據是奔賁古通。奔其機即賁其機。按機即几筵之幾。廟中所用物。賁文飾也。艮為幾。震為玄黃。故賁其機。得中。遇陰。故侮亡。</p><h3 id="象曰。渙奔其機。得願也。" tabindex="-1">象曰。渙奔其機。得願也。 <a class="header-anchor" href="#象曰。渙奔其機。得願也。" aria-label="Permalink to “象曰。渙奔其機。得願也。”">​</a></h3><p>陽遇重陰志行。故曰得願。舊解無有知其故者。</p><p>六三。渙其躬。無悔。</p><p>艮為躬。渙其躬。即行有文也。得陽應。故渙其躬無悔。</p><h3 id="象曰。渙其躬。志在外也。" tabindex="-1">象曰。渙其躬。志在外也。 <a class="header-anchor" href="#象曰。渙其躬。志在外也。" aria-label="Permalink to “象曰。渙其躬。志在外也。”">​</a></h3><p>巽為志。應在上。故志在外。</p><p>六四。渙其群。元吉。</p><p>渙有丘。匪夷所思。坎為眾為群。四體艮。艮為光明。在坎上。故渙其群。承陽故元吉。艮為丘。丘陵所以設險。今去坎險而復遇山險。故曰匪夷所思。夷平也。常也。言為恆常所不料也。</p><h3 id="象曰。渙其群元吉。光大也。" tabindex="-1">象曰。渙其群元吉。光大也。 <a class="header-anchor" href="#象曰。渙其群元吉。光大也。" aria-label="Permalink to “象曰。渙其群元吉。光大也。”">​</a></h3><p>遇陽故光大。按象曰光大。亦釋渙為文。</p><p>九五。渙汗其大號。渙王居。無咎。</p><p>吳先生曰。汗連綿字。愚按上林賦。采色皓（左水）汗。注玉石符采映耀也。渙汗益與汗同。與渙爛亦同。巽為號令。渙汗其大號。即頒佈光顯其號令。如風之無不屆也。艮為居。五君位。故曰王居。渙王居。言工居巍煥也。五履萬民之上。故光大如此也。得中故無咎。</p><h3 id="象曰。王居無咎。正位也。" tabindex="-1">象曰。王居無咎。正位也。 <a class="header-anchor" href="#象曰。王居無咎。正位也。" aria-label="Permalink to “象曰。王居無咎。正位也。”">​</a></h3><p>五位中正。故曰正位。五無應。然無咎者。以得中也。</p><p>上九。渙其血去逖出。無咎。</p><p>血古文恤字。逖與惕音同通用。小畜六四。血去惕出。與此同也。詁選為遠者非。應在三。坎為憂惕。王國維雲。古易狄同字。山海大荒東經井竹書皆雲王亥乇（左言）於有易。而楚辭天問作有狄。又簡狄古今表作簡遏。按漢書王商傳。車無怵愁憂。師古云。狄（下心）古惕字。故虞翻注云。逖憂也。與小畜六四詁惕為憂同。是虞即以邀惕同字。上九應在三。三坎為憂惕。而上九高出卦上。去坎險即遠。又不為互艮所止。與大畜上九義同。渙其光明貌。渙其恤去惕出。言光明在上。憂患自免也。句法與論語渙乎其有文章同。</p><h3 id="象曰。渙其血。遠害也。" tabindex="-1">象曰。渙其血。遠害也。 <a class="header-anchor" href="#象曰。渙其血。遠害也。" aria-label="Permalink to “象曰。渙其血。遠害也。”">​</a></h3><p>坎為害。上去三遠。故曰遠害。</p>',30)])])}const m=e(s,[["render",t]]);export{_ as __pageData,m as default};
